import{_ as r,C as i,o as l,c as h,ak as c,E as o,j as t,a}from"./chunks/framework.DxrHb2fb.js";const m=JSON.parse('{"title":"ColorSwatchPicker 颜色色块选择器","description":"","frontmatter":{},"headers":[],"relativePath":"components/color-swatch-picker.md","filePath":"components/color-swatch-picker.md","lastUpdated":1790043131000}'),s={name:"components/color-swatch-picker.md"};function n(b,d,p,u,k,w){const e=i("XhDemo");return l(),h("div",null,[d[0]||(d[0]=c('<h1 id="colorswatchpicker-颜色色块选择器" tabindex="-1">ColorSwatchPicker 颜色色块选择器 <a class="header-anchor" href="#colorswatchpicker-颜色色块选择器" aria-label="Permalink to &quot;ColorSwatchPicker 颜色色块选择器&quot;">​</a></h1><p>从一组固定颜色中选择一个：主题色、标签色、高亮色。每格是一个 <code>role=radio</code> 的色块，整组是一个 <code>radiogroup</code>，即把选项绘制为颜色的<a href="./radio-group">单选组</a>。需要自由调出任意颜色时使用<a href="./color-picker">颜色选择器</a>，它内嵌的预设色板使用的就是本组件。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/color-swatch-picker" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/color-swatch-picker.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/color-swatch-picker" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/color-swatch-picker" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/color-swatch-picker.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>提供一组颜色数据即自动铺开；每格是一个 radio，方向键在格子间移动并选中</p>',5)),o(e,{src:"color-swatch-picker/01-basic"}),d[1]||(d[1]=c('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;color-swatch-picker&quot;</code>：<strong><code>root</code></strong> · <code>label</code> · <strong><code>item</code></strong> · <strong><code>swatch</code></strong> · <code>indicator</code> · <code>hidden-input</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="手写格子" tabindex="-1">手写格子 <a class="header-anchor" href="#手写格子" aria-label="Permalink to &quot;手写格子&quot;">​</a></h3><p>不提供数据也可以：每格自行声明 value，名字与禁用写在格子上；半透明颜色铺在棋盘格上</p>',6)),o(e,{src:"color-swatch-picker/02-items"}),d[2]||(d[2]=t("h3",{id:"状态",tabindex:"-1"},[a("状态 "),t("a",{class:"header-anchor",href:"#状态","aria-label":'Permalink to "状态"'},"​")],-1)),d[3]||(d[3]=t("p",null,"禁用整组置灰、只读只阻止落值不阻止焦点、无效把描边转为警示色",-1)),o(e,{src:"color-swatch-picker/03-states"}),d[4]||(d[4]=t("h3",{id:"尺寸与语气",tabindex:"-1"},[a("尺寸与语气 "),t("a",{class:"header-anchor",href:"#尺寸与语气","aria-label":'Permalink to "尺寸与语气"'},"​")],-1)),d[5]||(d[5]=t("p",null,"格子边长跟随控件行高分三档；tone 决定选中描边与选中徽标使用哪族颜色",-1)),o(e,{src:"color-swatch-picker/04-size-tone"}),d[6]||(d[6]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>可选颜色是有限的一组，且每个颜色都有含义（品牌色、状态色、日历分类色）。</li><li>需要一次看到全部选项再挑选，不打开浮层。</li><li>表单需要提交一个颜色串，且不需要自由调色。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>需要自由调出任意颜色时，使用<a href="./color-picker">颜色选择器</a>，它把色板与取色面组合在一起。</li><li>只展示一个颜色、不接受选择时，使用<a href="./color-swatch">颜色色块</a>。</li><li>需要手动输入颜色串时，使用<a href="./color-field">颜色字段</a>。</li><li>选项不是颜色而是文字时，使用<a href="./radio-group">单选组</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>选中按颜色比较而不按字符串比较：<code>rgb(255, 0, 0)</code> 与 <code>#ff0000</code> 是同一格，受控 <code>value</code> 使用任一写法都能匹配。</li><li>与单选组同一套 roving tabindex：整组只占一个 Tab 位，四个方向键在格子间移动焦点并选中，到末端回绕，禁用格跳过；Space 选中当前格。</li><li>焦点从组外进入时落在已选中的格子，没有选中时落在第一格。</li><li><code>swatches</code> 提供数据：可访问名称与禁用从数据中读取，格子部件只需报告 <code>value</code>；不写默认内容时按数据自动铺开。</li><li>每格的色块面由 Swatch 家族绘制：无法解析的串只显示棋盘格，半透明颜色铺在棋盘格上。</li><li><code>readOnly</code> 时方向键照常移动焦点但不取值；<code>disabled</code> 整组置灰，格子仍可聚焦。</li><li>尺寸 sm / md / lg 三档：格子边长跟随控件行高，与旁边的按钮、字段等高。</li><li>选中徽标与色块的品牌描边随 <code>data-tone</code> 变化；徽标自带一圈画布色描边，落在任何颜色上都可见。</li><li>高对比模式下色块保留原色，选中描边与徽标换用系统高亮色；打印时徽标改为实边。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>内嵌在<a href="./color-picker">颜色选择器</a>的浮层中作为预设色板。</li><li>与<a href="./color-field">颜色字段</a>并排：色板选择常用色，字段输入精确值。</li><li>放入<a href="./field">表单字段</a>承接标题、说明与错误信息，<code>disabled</code> / <code>readOnly</code> / <code>invalid</code> / <code>required</code> 随字段下发。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>每格提供名称（<code>swatches[].label</code> 或部件的 <code>label</code>），读屏用户听到的应是“品牌红”而不是 <code>#e11d48</code>。</li><li>色板的颜色数量控制在一眼可扫完的范围，更多时改用<a href="./color-picker">颜色选择器</a>。</li><li>有初始值时使用 <code>defaultValue</code>，焦点进组时直接落在该格。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>用它做多选：一格只能选中一个；需要多选颜色时使用<a href="./checkbox-group">复选框组</a>配合<a href="./color-swatch">颜色色块</a>。</li><li>把颜色写成 <code>red</code> 等关键字：不在支持的写法内，该格只显示棋盘格。</li><li>同一组内放同一颜色的不同写法：它们会同时算作选中。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-color-swatch-picker&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhColorSwatchPickerItem</code> <code>XhColorSwatchPickerLabel</code> <code>XhColorSwatchPickerRoot</code></td></tr><tr><td>组合式函数</td><td><code>useColorSwatchPicker</code></td></tr><tr><td>状态机</td><td><code>colorSwatchPickerMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/color-swatch-picker.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>swatches</code></td><td><code>ColorSwatchPickerNode[]</code></td><td></td><td>格子数据，可及名与禁用的事实源。提供后格子部件只需声明 value。 未提供时回到名字与禁用都写在格子部件上的方式。</td></tr><tr><td><code>value</code></td><td><code>string | null</code></td><td></td><td>选中的颜色串。提供即受控：写入只发 onValueChange 不落内部值。写法不同的同一颜色也视为选中。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | null</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td></td><td>只读：不可选择，但仍可聚焦、方向键照常移动焦点，对比度不降低。</td></tr><tr><td><code>invalid</code></td><td><code>boolean</code></td><td></td><td>校验失败：只改变呈现，不阻止交互。</td></tr><tr><td><code>required</code></td><td><code>boolean</code></td><td></td><td>必填：随表单校验一起使用，只发无障碍属性，不自行拦截提交。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 &#39;ltr&#39;；只改写左右两键的语义。</td></tr><tr><td><code>name</code></td><td><code>string</code></td><td></td><td>表单字段名。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，影响格子的边长与间距。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：决定选中环与选中标记使用哪族颜色。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;ColorSwatchPickerTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ColorSwatchPickerValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化回调。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ColorSwatchPickerValueChangeDetails</code></td><td>选中值变化；detail 为 <code>{ value: string | null }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhColorSwatchPickerRoot</code></td><td><code>default</code></td><td><code>ColorSwatchPickerRootSlotProps</code></td><td></td></tr><tr><td><code>XhColorSwatchPickerRoot</code></td><td><code>label</code></td><td>—</td><td></td></tr></tbody></table><h3 id="状态-1" tabindex="-1">状态 <a class="header-anchor" href="#状态-1" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>item</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>swatch</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>indicator</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>hidden-input</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.FOCUS</code> · <code>GROUP.BLUR</code> · <code>FORM.RESET</code> · <code>PRESS.START</code> · <code>PRESS.END</code></p><p><strong>判据</strong>：<code>canPress</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string | null</code></td><td></td></tr><tr><td><code>swatches</code></td><td><code>readonly ColorSwatchPickerNodeMeta[]</code></td><td>由 swatches 推导的格子元信息，按数据顺序排列；未提供 swatches 时为空数组。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点在组外时为 null。</td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td>某个颜色串是否为当前选中的格：写法不同（<code>#f00</code> 与 <code>rgb(255,0,0)</code>）也视为同一颜色。</td></tr><tr><td><code>setValue</code></td><td><code>(next: string | null) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>一格：role=radio，颜色串是它的身份。</td></tr><tr><td><code>getSwatchProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>格内的色块面：使用 Swatch 家族绘制颜色，纯装饰。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;element&#39;]</code></td><td>选中标记（对号），纯装饰。</td></tr><tr><td><code>getHiddenInputProps</code></td><td><code>(props: ColorSwatchPickerItemProps) =&gt; T[&#39;input&#39;]</code></td><td>格子对应的隐藏原生 radio 输入，用于表单提交。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/radio/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the group</td><td>整组只占一个 Tab 位：焦点进入锚点格子（即选中的那格）；落到容器上时由容器转投锚点格子，锚点缺席或被禁用才落首个可停留格</td></tr><tr><td><code>ArrowDown</code> / <code>ArrowRight</code></td><td>focus in group, group not disabled</td><td>焦点移到下一个可停留格并选中，末格回绕到首格；dir=rtl 时改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowLeft</code></td><td>focus in group, group not disabled</td><td>焦点移到上一个可停留格并选中，首格回绕到末格；dir=rtl 时改由 ArrowRight 承担</td></tr><tr><td><code>Space</code></td><td>focus on item, item not disabled</td><td>选中当前格</td></tr><tr><td><code>Space</code></td><td>held on item, 格子未禁用且组未禁用、非只读</td><td>按住期间该格投影 data-pressed，与指针 :active 同一副按压面（换描边并缩放）；抬起或失焦撤下，按住途中整组转入禁用或只读也撤下。Enter 不是 radio 的激活键，按住它没有按压面</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-invalid</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-label</code></td><td>label.group</td></tr><tr><td><code>root</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>root</code></td><td><code>aria-readonly</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-required</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;radiogroup&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-checked</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-label</code></td><td>itemLabel(item)</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;radio&#39;</td></tr><tr><td><code>swatch</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>根是 <code>role=radiogroup</code>，名称取 label 部件，未提供时读 <code>translations.group</code>。</li><li>每格是 <code>role=radio</code> 并显式输出 <code>aria-checked</code>；名称依次取 <code>label</code>、<code>swatches</code> 中的 <code>label</code>、<code>translations.swatch(value)</code>，颜色串无法表达含义时务必提供名称。</li><li>禁用格用 <code>aria-disabled</code> 表达，仍可聚焦，仍是方向键的起点。</li><li>每格内有一个 <code>inert</code> 的隐藏原生 radio 承接表单提交，不进入焦点序列与可访问树。</li></ul><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/color-swatch-picker.css</code> 使用 <code>[data-scope=&quot;color-swatch-picker&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-required</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>swatch</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>swatch</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>swatch</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>swatch</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>swatch</code></td><td><code>data-xh-swatch</code></td><td>&#39;&#39;</td></tr><tr><td><code>swatch</code></td><td><code>data-xh-swatch-size</code></td><td>props.size</td></tr><tr><td><code>indicator</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr><tr><td><code>hidden-input</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-invalid</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-readonly</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>hidden-input</code></td><td><code>data-state</code></td><td>&#39;checked&#39; | &#39;unchecked&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-color-swatch-picker-gap</code></td><td><code>label</code><br><code>root</code></td><td><code>gap</code><br><code>margin-block-end</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-gap</code></td><td>color-swatch-picker 的 label、root 部件 gap、margin-block-end 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-icon-size</code></td><td><code>root</code></td><td><code>--xh-icon-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-mark</code></td><td>color-swatch-picker 的 root 部件 --xh-icon-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-bg</code></td><td><code>indicator</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-accent</code></td><td>color-swatch-picker 的 indicator 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-border</code></td><td><code>indicator</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-bg-canvas</code></td><td>color-swatch-picker 的 indicator 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-fg</code></td><td><code>indicator</code></td><td><code>background-color</code><br><code>color</code></td><td><code>default</code><br><code>empty</code></td><td><code>--xh-_tone-on</code></td><td>color-swatch-picker 的 indicator 部件 background-color、color 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-indicator-size</code></td><td><code>indicator</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-indicator</code></td><td>color-swatch-picker 的 indicator 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-item-radius</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-radius</code><br><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-radius、border-radius 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-item-size</code></td><td><code>item</code></td><td><code>block-size</code><br><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-_color-swatch-picker-cell</code></td><td>color-swatch-picker 的 item 部件 block-size、inline-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-fg</code></td><td><code>label</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>color-swatch-picker 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-fg-disabled</code></td><td><code>label</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>color-swatch-picker 的 label 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-font-size</code></td><td><code>label</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-text-label-size</code></td><td>color-swatch-picker 的 label 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-font-weight</code></td><td><code>label</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-text-label-weight</code></td><td>color-swatch-picker 的 label 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-label-gap</code></td><td><code>label</code></td><td><code>margin-block-end</code></td><td><code>default</code></td><td><code>--xh-space-1</code></td><td>color-swatch-picker 的 label 部件 margin-block-end 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-ring</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>state=checked</code></td><td><code>--xh-_tone</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>default</code></td><td><code>--xh-border-default</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border-hover</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>disabled</code><br><code>hover</code><br><code>not([data-disabled], [data-readonly], [data-state=&#39;checked&#39;])</code><br><code>readonly</code><br><code>state=checked</code></td><td><code>--xh-border-control-hover</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border-invalid</code></td><td><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>invalid</code></td><td><code>--xh-border-invalid</code></td><td>color-swatch-picker 的 swatch 部件 --xh-swatch-border 覆盖槽。</td></tr><tr><td><code>--xh-color-swatch-picker-swatch-border-pressed</code></td><td><code>item</code><br><code>swatch</code></td><td><code>--xh-swatch-border</code></td><td><code>disabled</code><br><code>is(:active, [data-pressed])</code><br><code>not([data-disabled], [data-readonly])</code><br><code>pressed</code><br><code>readonly</code></td><td><code>--xh-_tone</code></td><td>color-swatch-picker 的 item、swatch 部件 --xh-swatch-border 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>border-color</code> · <code>opacity</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="响应式" tabindex="-1">响应式 <a class="header-anchor" href="#响应式" aria-label="Permalink to &quot;响应式&quot;">​</a></h3><ul><li>格子排成可换行的网格，一行放不下时换行；粗指针下命中区是整格。</li></ul><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><ul><li><code>dir=&quot;rtl&quot;</code> 只对调左右方向键的语义，上下键不受影响；格子的排列顺序由文档方向决定。</li></ul>',59))])}const g=r(s,[["render",n]]);export{m as __pageData,g as default};
